class Codec:public VSTRING_CODEC{std::deque<std::string>names;public:uint32_t GetNum()override{return names.size();}uint32_t Convert(const char*s)override{return Convert(s,int(std::strlen(s)));}uint32_t Convert(const char*s,int32_t n)override{std::string x(s,n);for(uint32_t i=0;i<names.size();++i)if(names[i]==x)return i;names.push_back(x);return names.size()-1;}const char*Convert(uint32_t n)override{return names.at(n).c_str();}void VariableChanged()override{}};
int main(){Codec codec;ATTRIBUTES state(codec);auto*old=state.VerifyAttributeClass("c0");old->SetAttributeUseFloat("x",1);old->SetAttributeUseFloat("d",5);std::vector<storm_hull_damage::BeamSample>samples;assert(storm_hull_damage::readBeamSamples(old,samples)&&samples.empty());auto*entry=state.VerifyAttributeClass("c1");storm_hull_damage::BeamSample b;b.start={-1577.123f,4.56f,1009.345f};auto direction=storm_ship_hull::normalized({.4f,-.3f,.8f});b.direction={direction.x,direction.y,direction.z};auto t=storm_ship_laser::beamTangent(b);b.tangent={t.x,t.y,t.z};b.depth=.7;std::vector<storm_hull_damage::BeamSample>source{b};storm_hull_damage::writeBeamSamples(entry,source);assert(storm_hull_damage::readBeamSamples(entry,samples)&&samples.size()==1&&storm_ship_laser::valid(samples[0]));for(unsigned j=0;j<3;++j)assert(std::abs(samples[0].start[j]-b.start[j])<.006f);auto before=samples;entry->SetAttributeUseDword("samples",2);assert(!storm_hull_damage::readBeamSamples(entry,samples));assert(samples.size()==before.size()&&samples[0].start==before[0].start);entry->SetAttributeUseDword("samples",100000);assert(!storm_hull_damage::readBeamSamples(entry,samples));std::cout<<"real ATTRIBUTES legacy/finite schema/precision/missing sample/count rejection preserves output PASS\n";}
